    return hdc


def list_targets() -> list[str]:
    """返回 `hdc list targets` 报告的已连接设备序列号列表（过滤空槽位）。"""
    hdc = find_hdc()
    result = subprocess.run(
        [hdc, "list", "targets"],
        capture_output=True,
        text=True,
        check=True,
        timeout=10,
    )
